import {useCallback,useEffect,useState} from 'react';
import {AlertTriangle,Check,Clock3,MapPin,ShieldCheck,UserPlus,UsersRound,X} from 'lucide-react';
import {assignClientTeam,deactivateTeamMember,inviteTeamMember,listClientTeam,listTeamInvitations,listTeamMembers,listTeamRoles,removeClientTeamAssignment,resendTeamInvitation,suspendTeamMember,updateTeamMember} from '../../lib/practiceOperationsApi';
import {Button,PageHeader,Surface} from './ui/ExternalUI';
import {isConsultantFeatureVisible} from '../../lib/consultantFeatureVisibility.mjs';

const LABEL={PRACTICE_OWNER:'Practice owner',PRACTICE_ADMIN:'Practice admin',PRACTITIONER:'Practitioner',ASSISTANT:'Assistant',RECEPTIONIST:'Receptionist'};
const ROLE_COPY={PRACTICE_OWNER:'Full practice governance. Private practitioner notes remain separately protected.',PRACTICE_ADMIN:'Team and operational administration without private-note access.',PRACTITIONER:'Professional care for assigned clients, constrained by profession capabilities.',ASSISTANT:'Operational tasks, follow-ups, resources, and scheduling where permitted.',RECEPTIONIST:'Contact and scheduling access without clinical or professional detail.'};

function Status({value}){const tone=value==='ACTIVE'?'bg-emerald-50 text-emerald-700':value==='INVITED'?'bg-blue-50 text-blue-700':'bg-amber-50 text-amber-800';return <span className={`inline-flex min-h-7 items-center rounded-full px-2.5 text-xs font-semibold ${tone}`}>{value.toLowerCase().replaceAll('_',' ')}</span>}

export function ExternalTeam(){
  const [tab,setTab]=useState('members');const [members,setMembers]=useState([]);const [invitations,setInvitations]=useState([]);const [roles,setRoles]=useState([]);const [permissions,setPermissions]=useState([]);
  const [state,setState]=useState('loading');const [error,setError]=useState('');const [inviteOpen,setInviteOpen]=useState(false);const [editing,setEditing]=useState(null);
  const load=useCallback(async()=>{setState('loading');setError('');try{const [team,invites,definitions]=await Promise.all([listTeamMembers(),listTeamInvitations(),listTeamRoles()]);setMembers(team.items||[]);setPermissions(team.permissions||[]);setInvitations(invites.items||[]);setRoles(definitions.roles||[]);setState('ready')}catch(err){setError(err.message);setState('error')}},[]);
  useEffect(()=>{void load()},[load]);const canManage=permissions.includes('TEAM_MANAGE');
  return <div className="space-y-5"><Surface className="border-white/80 bg-[#f9f8f4] shadow-none"><PageHeader eyebrow="Practice operations" title="Team" subtitle="Govern roles, invitations, and access without exposing private professional information." actions={canManage?<Button icon={UserPlus} onClick={()=>setInviteOpen(true)}>Invite member</Button>:null}/></Surface>
    <div className="flex gap-2 overflow-x-auto" role="tablist" aria-label="Team sections">{[['members','Members'],['invitations','Invitations'],['roles','Roles & access']].map(([id,label])=><button key={id} role="tab" aria-selected={tab===id} onClick={()=>setTab(id)} className={`min-h-11 shrink-0 rounded-xl px-4 text-sm font-semibold ${tab===id?'bg-slate-950 text-white':'border border-slate-200 bg-white text-slate-600'}`}>{label}</button>)}</div>
    {state==='loading'?<Surface><p role="status" className="py-12 text-center text-sm text-slate-500">Loading authorised team access…</p></Surface>:state==='error'?<Surface className="border-amber-200 bg-amber-50"><div role="alert"><h2 className="font-bold text-amber-950">Team access unavailable</h2><p className="mt-2 text-sm text-amber-900">{error}</p><Button className="mt-4" onClick={load}>Retry</Button></div></Surface>:tab==='members'?<Members items={members} canManage={canManage} onEdit={setEditing} reload={load}/>:tab==='invitations'?<Invitations items={invitations} canManage={canManage} reload={load}/>:<Roles items={roles}/>}
    {inviteOpen&&<InvitePanel onClose={()=>setInviteOpen(false)} onSent={async()=>{setInviteOpen(false);await load()}}/>}
    {editing&&<RoleEdit member={editing} onClose={()=>setEditing(null)} onSaved={async()=>{setEditing(null);await load()}}/>}
  </div>
}

function Members({items,canManage,onEdit,reload}){const changeStatus=async(item,kind)=>{if(!window.confirm(`${kind==='suspend'?'Suspend':'Deactivate'} ${item.display_name}? Their current access will be removed.`))return;await(kind==='suspend'?suspendTeamMember(item.id):deactivateTeamMember(item.id));await reload()};return <Surface className="overflow-hidden p-0"><div className="hidden grid-cols-[1.3fr_.9fr_1fr_.6fr_.8fr_auto] gap-4 border-b bg-slate-50 px-5 py-3 text-[11px] font-semibold uppercase tracking-wider text-slate-500 md:grid"><span>Member</span><span>Role</span><span>Profession</span><span>Clients</span><span>Status</span><span>Actions</span></div>{items.length?<div className="divide-y divide-slate-100">{items.map(item=><article key={item.id||item.user_id} className="grid gap-3 p-5 md:grid-cols-[1.3fr_.9fr_1fr_.6fr_.8fr_auto] md:items-center"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-xl bg-blue-50 font-bold text-blue-700">{(item.display_name||'TM').split(' ').map(value=>value[0]).join('').slice(0,2)}</span><div><h3 className="font-semibold text-slate-950">{item.display_name||'Team member'}</h3>{item.location_code&&<p className="mt-1 flex items-center gap-1 text-xs text-slate-500"><MapPin size={12}/>{item.location_code}</p>}</div></div><p className="text-sm font-medium">{LABEL[item.role]||item.role}</p><p className="text-sm text-slate-600">{item.profession_code?.replaceAll('_',' ')||'Not applicable'}</p><p className="text-sm"><span className="md:hidden">Assigned clients: </span>{item.assigned_clients_count||0}</p><Status value={item.status}/>{canManage&&item.id&&!item.legacy_solo?<div className="flex flex-wrap gap-1"><button onClick={()=>onEdit(item)} className="min-h-11 rounded-lg border px-2 text-xs font-semibold">Manage access</button>{item.status==='ACTIVE'&&<button onClick={()=>changeStatus(item,'suspend')} className="min-h-11 rounded-lg px-2 text-xs font-semibold text-amber-800">Suspend</button>}<button onClick={()=>changeStatus(item,'deactivate')} className="min-h-11 rounded-lg px-2 text-xs font-semibold text-red-700">Deactivate</button></div>:<span className="text-xs text-slate-400">Protected</span>}</article>)}</div>:<div className="p-10 text-center"><UsersRound className="mx-auto text-slate-400"/><h3 className="mt-3 font-bold">No team profiles yet</h3><p className="mt-1 text-sm text-slate-500">Invite a member when the practice is ready to collaborate.</p></div>}</Surface>}

function Invitations({items,canManage,reload}){const resend=async id=>{await resendTeamInvitation(id);await reload()};return <Surface>{items.length?<div className="grid gap-3">{items.map(item=><article key={item.id} className="flex flex-col justify-between gap-4 rounded-2xl border border-slate-200 p-4 sm:flex-row sm:items-center"><div><h3 className="font-semibold">{item.display_name}</h3><p className="mt-1 text-sm text-slate-500">{item.email} · {LABEL[item.role]}</p><p className="mt-2 flex items-center gap-1 text-xs text-slate-500"><Clock3 size={13}/>Expires {new Date(item.expires_at).toLocaleDateString()}</p></div><div className="flex items-center gap-2"><Status value={item.status}/>{canManage&&item.status==='INVITED'&&<button onClick={()=>resend(item.id)} className="min-h-11 rounded-xl border border-slate-200 px-3 text-sm font-semibold">Resend</button>}</div></article>)}</div>:<div className="py-10 text-center"><Check className="mx-auto text-emerald-600"/><p className="mt-3 font-semibold">No pending invitations</p></div>}</Surface>}

function Roles({items}){const showCounts=isConsultantFeatureVisible('governedPermissionCounts');return <div className="grid gap-4 lg:grid-cols-2">{items.map(item=><Surface key={item.role}><div className="flex items-start gap-3"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-slate-950 text-white"><ShieldCheck size={20}/></span><div><h3 className="font-bold">{LABEL[item.role]}</h3><p className="mt-1 text-sm leading-6 text-slate-600">{ROLE_COPY[item.role]}</p></div></div><details className="mt-4 rounded-xl bg-slate-50 p-3"><summary className="cursor-pointer text-sm font-semibold">{showCounts?`${item.permissions.length} governed permissions`:'Governed permissions'}</summary><div className="mt-3 flex flex-wrap gap-1.5">{item.permissions.map(value=><span key={value} className="rounded-lg bg-white px-2 py-1 text-[11px] text-slate-600">{value.replaceAll('_',' ').toLowerCase()}</span>)}</div></details></Surface>)}</div>}

function InvitePanel({onClose,onSent}){const [form,setForm]=useState({name:'',email:'',role:'PRACTITIONER',profession_code:'',specialisation:'',location_code:''});const [saving,setSaving]=useState(false);const [error,setError]=useState('');const submit=async event=>{event.preventDefault();setSaving(true);setError('');try{await inviteTeamMember({...form,profession_code:form.role==='PRACTITIONER'?form.profession_code:null,permission_grants:[],permission_restrictions:[]});await onSent()}catch(err){setError(err.message);setSaving(false)}};return <div className="fixed inset-0 z-[80] bg-slate-950/50" onClick={onClose}><aside role="dialog" aria-modal="true" aria-labelledby="invite-title" onClick={event=>event.stopPropagation()} className="ml-auto h-full w-full max-w-lg overflow-y-auto bg-white p-5 shadow-2xl sm:p-7"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold uppercase tracking-wider text-blue-700">Governed access</p><h2 id="invite-title" className="mt-1 text-2xl font-bold">Invite team member</h2></div><button aria-label="Close invitation" onClick={onClose} className="grid h-11 w-11 place-items-center rounded-xl border"><X/></button></div>{error&&<p role="alert" className="mt-5 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<form onSubmit={submit} className="mt-6 space-y-4">{[['name','Name','text'],['email','Email','email']].map(([key,label,type])=><label key={key} className="block text-sm font-semibold">{label}<input required type={type} value={form[key]} onChange={event=>setForm({...form,[key]:event.target.value})} className="mt-1 min-h-12 w-full rounded-xl border border-slate-200 px-3 font-normal outline-none focus:border-blue-600"/></label>)}<label className="block text-sm font-semibold">Role<select value={form.role} onChange={event=>setForm({...form,role:event.target.value})} className="mt-1 min-h-12 w-full rounded-xl border border-slate-200 px-3 font-normal">{['PRACTICE_ADMIN','PRACTITIONER','ASSISTANT','RECEPTIONIST'].map(role=><option key={role} value={role}>{LABEL[role]}</option>)}</select></label>{form.role==='PRACTITIONER'&&<label className="block text-sm font-semibold">Profession<input required value={form.profession_code} onChange={event=>setForm({...form,profession_code:event.target.value.toUpperCase().replaceAll(' ','_')})} placeholder="e.g. PHYSIOTHERAPIST" className="mt-1 min-h-12 w-full rounded-xl border border-slate-200 px-3 font-normal"/></label>}<label className="block text-sm font-semibold">Specialisation <span className="font-normal text-slate-400">optional</span><input value={form.specialisation} onChange={event=>setForm({...form,specialisation:event.target.value})} className="mt-1 min-h-12 w-full rounded-xl border border-slate-200 px-3 font-normal"/></label><label className="block text-sm font-semibold">Location <span className="font-normal text-slate-400">optional</span><input value={form.location_code} onChange={event=>setForm({...form,location_code:event.target.value})} className="mt-1 min-h-12 w-full rounded-xl border border-slate-200 px-3 font-normal"/></label><div className="rounded-2xl bg-blue-50 p-4"><p className="text-sm font-bold text-blue-950">{LABEL[form.role]}</p><p className="mt-1 text-sm leading-6 text-blue-900">{ROLE_COPY[form.role]}</p>{['PRACTICE_ADMIN','ASSISTANT','RECEPTIONIST'].includes(form.role)&&<p className="mt-2 flex gap-2 text-xs font-semibold text-blue-950"><AlertTriangle size={15}/>Private notes are not included.</p>}</div><Button type="submit" disabled={saving} className="w-full">{saving?'Sending invitation…':'Send secure invitation'}</Button></form></aside></div>}

function RoleEdit({member,onClose,onSaved}){const [role,setRole]=useState(member.role);const [profession,setProfession]=useState(member.profession_code||'');const [confirmed,setConfirmed]=useState(false);const [saving,setSaving]=useState(false);const [error,setError]=useState('');const changed=role!==member.role;const removed=member.role==='PRACTITIONER'&&role!=='PRACTITIONER'?['session notes','assessments','plans','progress and private notes']:[];const save=async()=>{setSaving(true);setError('');try{await updateTeamMember(member.id,{role,profession_code:role==='PRACTITIONER'?profession:null,specialisation:member.specialisation||null,location_code:member.location_code||null,permission_grants:[],permission_restrictions:[],practice_wide_client_access:Boolean(member.practice_wide_client_access)});await onSaved()}catch(reason){setError(reason.message);setSaving(false)}};return <div className="fixed inset-0 z-[90] grid place-items-end bg-slate-950/50 sm:place-items-center sm:p-4"><section role="dialog" aria-modal="true" aria-labelledby="role-edit-title" className="w-full max-w-lg rounded-t-3xl bg-white p-6 sm:rounded-3xl"><div className="flex items-center justify-between"><h2 id="role-edit-title" className="text-xl font-bold">Manage access</h2><button onClick={onClose} aria-label="Close role editor" className="grid h-11 w-11 place-items-center rounded-xl border"><X/></button></div><p className="mt-1 text-sm text-slate-500">{member.display_name}</p>{error&&<p role="alert" className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<label className="mt-5 block text-sm font-semibold">Role<select value={role} onChange={event=>{setRole(event.target.value);setConfirmed(false)}} className="mt-2 min-h-12 w-full rounded-xl border px-3">{['PRACTICE_ADMIN','PRACTITIONER','ASSISTANT','RECEPTIONIST'].map(value=><option key={value} value={value}>{LABEL[value]}</option>)}</select></label>{role==='PRACTITIONER'&&<label className="mt-4 block text-sm font-semibold">Profession<input required value={profession} onChange={event=>setProfession(event.target.value.toUpperCase().replaceAll(' ','_'))} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label>}<div className="mt-4 rounded-2xl bg-amber-50 p-4"><p className="font-semibold text-amber-950">Impact summary</p><p className="mt-1 text-sm text-amber-900">{changed?`Changing ${LABEL[member.role]} to ${LABEL[role]} updates governed access immediately.`:'No role change selected.'}</p>{removed.map(value=><p key={value} className="mt-2 text-sm text-amber-900">Access removed: {value}</p>)}</div>{changed&&<label className="mt-4 flex min-h-11 items-center gap-3 text-sm font-semibold"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)} className="h-5 w-5"/>I understand this access impact</label>}<div className="mt-6 flex justify-end gap-2"><button onClick={onClose} className="min-h-11 rounded-xl border px-4 font-semibold">Cancel</button><button onClick={save} disabled={saving||(changed&&!confirmed)||(role==='PRACTITIONER'&&!profession)} className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white disabled:opacity-40">{saving?'Saving…':'Confirm access change'}</button></div></section></div>}

export function ClientCareTeam({clientId}){const [members,setMembers]=useState([]);const [assignments,setAssignments]=useState([]);const [permissions,setPermissions]=useState([]);const [state,setState]=useState('loading');const [error,setError]=useState('');const [form,setForm]=useState({user_id:'',assignment_role:'SECONDARY_PRACTITIONER',reason:''});const load=useCallback(async()=>{setState('loading');setError('');try{const [team,care]=await Promise.all([listTeamMembers(),listClientTeam(clientId)]);setMembers(team.items||[]);setPermissions(team.permissions||[]);setAssignments(care.items||[]);setState('ready')}catch(reason){setError(reason.message);setState('error')}},[clientId]);useEffect(()=>{void load()},[load]);const available=members.filter(member=>member.id&&member.status==='ACTIVE');const canAssign=permissions.includes('CLIENT_ASSIGN');const assign=async event=>{event.preventDefault();try{await assignClientTeam(clientId,{...form,reason:form.reason||null});setForm({user_id:'',assignment_role:'SECONDARY_PRACTITIONER',reason:''});await load()}catch(reason){setError(reason.message)}};const remove=async item=>{if(!window.confirm(`Remove ${item.display_name} from this client's care team? Historical assignment remains preserved.`))return;await removeClientTeamAssignment(clientId,item.id);await load()};if(state==='loading')return <div role="status" className="rounded-2xl bg-white p-10 text-center">Loading care team…</div>;if(state==='error')return <div role="alert" className="rounded-2xl bg-red-50 p-5 text-red-800">{error}<button onClick={load} className="ml-2 min-h-11 font-bold">Retry</button></div>;return <div className="grid gap-5 xl:grid-cols-[1fr_360px]"><Surface><h3 className="text-xl font-bold">Care team</h3><p className="mt-1 text-sm text-slate-500">Current and historical client authority, without rewriting prior ownership.</p>{assignments.length?<div className="mt-5 divide-y">{assignments.map(item=><article key={item.id} className={`flex flex-col justify-between gap-3 py-4 sm:flex-row sm:items-center ${item.ended_at?'opacity-55':''}`}><div><p className="font-semibold">{item.display_name}</p><p className="mt-1 text-sm text-slate-500">{item.assignment_role.replaceAll('_',' ')} · {item.profession_code?.replaceAll('_',' ')||item.role}</p>{item.ended_at&&<p className="mt-1 text-xs">Ended {new Date(item.ended_at).toLocaleDateString()}</p>}</div>{canAssign&&!item.ended_at&&<button onClick={()=>remove(item)} className="min-h-11 rounded-xl border border-red-200 px-3 text-sm font-semibold text-red-700">Remove assignment</button>}</article>)}</div>:<p className="mt-5 rounded-2xl border border-dashed p-8 text-center text-sm text-slate-500">No governed care-team assignment yet.</p>}</Surface>{canAssign&&<Surface><h3 className="font-bold">Assign team member</h3><form onSubmit={assign} className="mt-4 space-y-4"><label className="block text-sm font-semibold">Member<select required value={form.user_id} onChange={event=>setForm({...form,user_id:event.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="">Select member</option>{available.map(item=><option key={item.user_id} value={item.user_id}>{item.display_name} · {LABEL[item.role]}</option>)}</select></label><label className="block text-sm font-semibold">Assignment<select value={form.assignment_role} onChange={event=>setForm({...form,assignment_role:event.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="PRIMARY_PRACTITIONER">Primary practitioner</option><option value="SECONDARY_PRACTITIONER">Secondary practitioner</option><option value="CARE_TEAM_MEMBER">Assigned staff</option></select></label><label className="block text-sm font-semibold">Reason <span className="font-normal text-slate-400">optional</span><textarea value={form.reason} onChange={event=>setForm({...form,reason:event.target.value})} className="mt-2 min-h-24 w-full rounded-xl border p-3"/></label><Button type="submit" disabled={!form.user_id} className="w-full">Assign</Button></form></Surface>}</div>}
